// ExactMacServer is the server API for ExactMac service.
// All implementations must embed UnimplementedExactMacServer
// for forward compatibility.
//
// ExactMac is the primary service for automating macOS applications.
type ExactMacServer interface {
	// Gets one exact installed application bundle.
	GetApplicationBundle(context.Context, *GetApplicationBundleRequest) (*ApplicationBundle, error)
	// Lists discoverable installed application bundles without opening them.
	ListApplicationBundles(context.Context, *ListApplicationBundlesRequest) (*ListApplicationBundlesResponse, error)
	// Opens one exact installed application bundle.
	OpenApplication(context.Context, *OpenApplicationRequest) (*OpenApplicationResponse, error)
	// Gets one exact running application process instance.
	GetApplication(context.Context, *GetApplicationRequest) (*Application, error)
	// Lists exact currently running user application process instances.
	ListApplications(context.Context, *ListApplicationsRequest) (*ListApplicationsResponse, error)
	// Activates one exact running application process instance.
	ActivateApplication(context.Context, *ActivateApplicationRequest) (*ActivateApplicationResponse, error)
	// Closes an exact tracked application instance and stops tracking it after
	// the owned process is observed to exit.
	CloseApplication(context.Context, *CloseApplicationRequest) (*CloseApplicationResponse, error)
	// Creates an input action to be executed.
	CreateInput(context.Context, *CreateInputRequest) (*Input, error)
	// Gets a specific input.
	GetInput(context.Context, *GetInputRequest) (*Input, error)
	// Lists inputs for an application or globally.
	ListInputs(context.Context, *ListInputsRequest) (*ListInputsResponse, error)
	// Traverses the accessibility tree of an application.
	TraverseAccessibility(context.Context, *TraverseAccessibilityRequest) (*TraverseAccessibilityResponse, error)
	// Streams accessibility tree changes for an application.
	WatchAccessibility(*WatchAccessibilityRequest, grpc.ServerStreamingServer[WatchAccessibilityResponse]) error
	// Gets a specific window.
	GetWindow(context.Context, *GetWindowRequest) (*Window, error)
	// Lists windows for an application.
	ListWindows(context.Context, *ListWindowsRequest) (*ListWindowsResponse, error)
	// Gets the detailed state (AX) of a window.
	GetWindowState(context.Context, *GetWindowStateRequest) (*WindowState, error)
	// Focuses a specific window.
	FocusWindow(context.Context, *FocusWindowRequest) (*Window, error)
	// Moves a window to a new position.
	MoveWindow(context.Context, *MoveWindowRequest) (*Window, error)
	// Resizes a window.
	ResizeWindow(context.Context, *ResizeWindowRequest) (*Window, error)
	// Minimizes a window.
	MinimizeWindow(context.Context, *MinimizeWindowRequest) (*Window, error)
	// Restores a minimized window.
	RestoreWindow(context.Context, *RestoreWindowRequest) (*Window, error)
	// Closes a window.
	CloseWindow(context.Context, *CloseWindowRequest) (*CloseWindowResponse, error)
	// Finds elements matching a selector.
	FindElements(context.Context, *FindElementsRequest) (*FindElementsResponse, error)
	// Finds elements within a screen region.
	FindRegionElements(context.Context, *FindRegionElementsRequest) (*FindRegionElementsResponse, error)
	// Gets a specific element.
	GetElement(context.Context, *GetElementRequest) (*Element, error)
	// Lists retained element resources for an application.
	ListElements(context.Context, *ListElementsRequest) (*ListElementsResponse, error)
	// Clicks an element.
	ClickElement(context.Context, *ClickElementRequest) (*ClickElementResponse, error)
	// Writes an element's value.
	WriteElementValue(context.Context, *WriteElementValueRequest) (*WriteElementValueResponse, error)
	// Gets available actions for an element.
	GetElementActions(context.Context, *GetElementActionsRequest) (*ElementActions, error)
	// Performs an accessibility action on an element.
	PerformElementAction(context.Context, *PerformElementActionRequest) (*PerformElementActionResponse, error)
	// Waits for an element to appear (long-running operation).
	WaitElement(context.Context, *WaitElementRequest) (*longrunningpb.Operation, error)
	// Waits for an element to reach a specific state (long-running operation).
	WaitElementState(context.Context, *WaitElementStateRequest) (*longrunningpb.Operation, error)
	// Creates an observation (long-running operation).
	CreateObservation(context.Context, *CreateObservationRequest) (*longrunningpb.Operation, error)
	// Gets an observation.
	GetObservation(context.Context, *GetObservationRequest) (*Observation, error)
	// Lists observations for an application.
	ListObservations(context.Context, *ListObservationsRequest) (*ListObservationsResponse, error)
	// Cancels an observation.
	CancelObservation(context.Context, *CancelObservationRequest) (*Observation, error)
	// Streams observation events.
	StreamObservations(*StreamObservationsRequest, grpc.ServerStreamingServer[StreamObservationsResponse]) error
	// Creates a session.
	CreateSession(context.Context, *CreateSessionRequest) (*Session, error)
	// Gets a session.
	GetSession(context.Context, *GetSessionRequest) (*Session, error)
	// Lists sessions.
	ListSessions(context.Context, *ListSessionsRequest) (*ListSessionsResponse, error)
	// Deletes a session.
	DeleteSession(context.Context, *DeleteSessionRequest) (*emptypb.Empty, error)
	// Begins a transaction within a session.
	BeginTransaction(context.Context, *BeginTransactionRequest) (*BeginTransactionResponse, error)
	// Commits a transaction.
	CommitTransaction(context.Context, *CommitTransactionRequest) (*Transaction, error)
	// Rolls back a transaction.
	RollbackTransaction(context.Context, *RollbackTransactionRequest) (*Transaction, error)
	// Gets a session state snapshot.
	GetSessionSnapshot(context.Context, *GetSessionSnapshotRequest) (*SessionSnapshot, error)
	// Captures a full screen screenshot.
	CaptureScreenshot(context.Context, *CaptureScreenshotRequest) (*CaptureScreenshotResponse, error)
	// Captures a screenshot of a specific window.
	CaptureWindowScreenshot(context.Context, *CaptureWindowScreenshotRequest) (*CaptureWindowScreenshotResponse, error)
	// Captures a screenshot of a specific element.
	CaptureElementScreenshot(context.Context, *CaptureElementScreenshotRequest) (*CaptureElementScreenshotResponse, error)
	// Captures a screenshot of a screen region.
	CaptureRegionScreenshot(context.Context, *CaptureRegionScreenshotRequest) (*CaptureRegionScreenshotResponse, error)
	// Lists displays attached to the system.
	ListDisplays(context.Context, *ListDisplaysRequest) (*ListDisplaysResponse, error)
	// Gets a specific display.
	GetDisplay(context.Context, *GetDisplayRequest) (*Display, error)
	// Captures the current cursor position.
	// Returns coordinates in Global Display Coordinates (top-left origin).
	CaptureCursorPosition(context.Context, *CaptureCursorPositionRequest) (*CaptureCursorPositionResponse, error)
	// Gets clipboard contents.
	GetClipboard(context.Context, *GetClipboardRequest) (*Clipboard, error)
	// Writes clipboard contents.
	WriteClipboard(context.Context, *WriteClipboardRequest) (*WriteClipboardResponse, error)
	// Clears clipboard contents.
	ClearClipboard(context.Context, *ClearClipboardRequest) (*ClearClipboardResponse, error)
	// Gets clipboard history (if available).
	GetClipboardHistory(context.Context, *GetClipboardHistoryRequest) (*ClipboardHistory, error)
	// Automates an open file dialog.
	AutomateOpenFileDialog(context.Context, *AutomateOpenFileDialogRequest) (*AutomateOpenFileDialogResponse, error)
	// Automates a save file dialog.
	AutomateSaveFileDialog(context.Context, *AutomateSaveFileDialogRequest) (*AutomateSaveFileDialogResponse, error)
	// Creates a macro.
	CreateMacro(context.Context, *CreateMacroRequest) (*Macro, error)
	// Gets a macro.
	GetMacro(context.Context, *GetMacroRequest) (*Macro, error)
	// Lists macros.
	ListMacros(context.Context, *ListMacrosRequest) (*ListMacrosResponse, error)
	// Gets one grant by name.
	GetGrant(context.Context, *GetGrantRequest) (*Grant, error)
	// Lists the permissions currently held, and who holds them.
	//
	// An agent that cannot see what it already holds cannot work inside a grant it was given,
	// so it asks again — and asking again costs the operator a prompt they have already
	// answered. Introspection is therefore part of the contract, not a convenience.
	ListGrants(context.Context, *ListGrantsRequest) (*ListGrantsResponse, error)
	// Asks the operator to pre-authorize a declared set of capabilities for a bounded time,
	// before they are needed.
	//
	// The whole point is ANTICIPATION: an agent that knows it will need clipboard and tree
	// access across a refactor should say so once, at the start, rather than interrupting the
	// work at every step. What it may not do is ask for more than it declared — an envelope
	// may not cover an undeclared capability, can never be global, and never outlives the
	// duration it was granted for.
	PreauthorizeEnvelope(context.Context, *PreauthorizeEnvelopeRequest) (*PreauthorizeEnvelopeResponse, error)
	// Updates a macro.
	UpdateMacro(context.Context, *UpdateMacroRequest) (*Macro, error)
	// Deletes a macro.
	DeleteMacro(context.Context, *DeleteMacroRequest) (*emptypb.Empty, error)
	// Executes a macro (long-running operation).
	ExecuteMacro(context.Context, *ExecuteMacroRequest) (*longrunningpb.Operation, error)
	// Executes an AppleScript.
	ExecuteAppleScript(context.Context, *ExecuteAppleScriptRequest) (*ExecuteAppleScriptResponse, error)
	// Executes JavaScript for Automation (JXA).
	ExecuteJavaScript(context.Context, *ExecuteJavaScriptRequest) (*ExecuteJavaScriptResponse, error)
	// Executes a shell command.
	ExecuteShellCommand(context.Context, *ExecuteShellCommandRequest) (*ExecuteShellCommandResponse, error)
	// Validates a script without executing.
	ValidateScript(context.Context, *ValidateScriptRequest) (*ValidateScriptResponse, error)
	// Gets scripting dictionaries.
	GetScriptingDictionaryCatalog(context.Context, *GetScriptingDictionaryCatalogRequest) (*ScriptingDictionaryCatalog, error)
	mustEmbedUnimplementedExactMacServer()
}

